/* Shared by the figures of the two "reinforcement learning" slides of the Foundations chapter (assets/anim/rl-*.js).
 *
 * Data: window.RLDemo (assets/anim/rl-data.js, generated by tools/fig/rl_rollouts.py). Real MuJoCo rollouts of a humanoid that
 * learns to stand with PPO: the untrained policy, the policy after 0.25 M samples, after 1.0 M samples, and the last one acting
 * with its mean. Nothing in these figures is hand-animated: poses, rewards and reward terms are replayed from that file.
 *
 * RLKit.at(t)        where the loop figure is at time t (which rollout, which step, which phase of the step); pure function of t
 * RLKit.pose(e, s)   the 20 body points of rollout e at (fractional) step s
 * RLKit.stick(...)   a 2D mannequin drawn from those points
 */
(function () {
  'use strict';
  var K = window.RLKit = {};
  var A = window.DeckAnim.A;

  // ---- timeline of the loop figure: three rollouts one after the other, each starting in slow motion and speeding up to real time
  var SLOW0 = [1.5, 1.5, 1.1, 0.7, 0.45, 0.28, 0.17, 0.1, 0.06];   // seconds on screen for the first steps of the first rollout
  var SLOW1 = [0.8, 0.5, 0.3, 0.18, 0.1, 0.06];                    // the later rollouts get up to speed sooner
  var RT = 1 / 30;                                                 // then real time: one policy step = 1/30 s
  K.TAIL = 0.4;                                                    // the last state and reward travel back
  K.HOLD = 2.4;                                                    // the finished rollout stays on screen (includes TAIL)
  // phases inside one step (fractions of its duration)
  K.P_S = 0.30;       // 0 .. P_S      state (and the previous reward) travel simulator -> policy
  K.P_DROP = 0.45;    // P_S .. P_DROP the reward drops into the rollout strip, the policy network fires
  K.P_A0 = 0.42;      // P_A0 .. P_A1  the action travels policy -> simulator
  K.P_A1 = 0.70;      // P_A1 .. 1     the simulator advances by one step

  var tl = null;
  K.timeline = function () {
    if (tl) return tl;
    var D = window.RLDemo, eps = [], T = 0;
    for (var e = 0; e < 3; e++) {
      var n = D.episodes[e].n, slow = e === 0 ? SLOW0 : SLOW1, st = [], du = [], t = 0;
      for (var k = 0; k < n; k++) { var d = k < slow.length ? slow[k] : RT; st.push(t); du.push(d); t += d; }
      eps.push({ e: e, n: n, start: st, dur: du, run: t, total: t + K.HOLD, t0: T });
      T += t + K.HOLD;
    }
    tl = { eps: eps, period: T };
    return tl;
  };

  K.at = function (t) {
    var L = K.timeline(), D = window.RLDemo;
    var tt = ((t % L.period) + L.period) % L.period, ep = L.eps[2], i;
    for (i = 0; i < 3; i++) if (tt < L.eps[i].t0 + L.eps[i].total) { ep = L.eps[i]; break; }
    var te = tt - ep.t0, k, u, dur, hold = te >= ep.run;
    if (hold) { k = ep.n; u = A.clamp((te - ep.run) / K.TAIL, 0, 1); dur = K.TAIL; }
    else {
      var lo = 0, hi = ep.n - 1;
      while (lo < hi) { var m = (lo + hi + 1) >> 1; if (ep.start[m] <= te) lo = m; else hi = m - 1; }
      k = lo; dur = ep.dur[k]; u = A.clamp((te - ep.start[k]) / dur, 0, 1);
    }
    var slow = hold ? 0 : A.clamp((dur - 0.07) / 0.2, 0, 1);                                       // 1: single tokens can be followed, 0: real time
    var u0 = K.P_A1 * A.clamp((dur - 0.05) / 0.4, 0, 1);
    var simT = hold ? ep.n : k + A.ramp(u, u0, 1 + 1e-9);                                          // pose time, in policy steps
    var landed = A.clamp(u >= K.P_DROP ? k : k - 1, 0, ep.n);                                      // rewards that have reached the strip
    return { ep: ep, e: ep.e, D: D.episodes[ep.e], te: te, k: k, u: u, dur: dur, hold: hold, th: te - ep.run, slow: slow, simT: simT, landed: landed, tt: tt };
  };
  /** time (on the figure's clock) at which rollout e is finished and fully on screen: for data-anim-still */
  K.stillOf = function (e) { var L = K.timeline(); return L.eps[e].t0 + L.eps[e].run + 1.2; };

  // ---- body points
  K.pose = function (e, s) {
    var P = window.RLDemo.episodes[e].pts, n = P.length - 1;
    s = A.clamp(s, 0, n);
    var i = Math.min(n - 1, Math.floor(s)), w = s - i, a = P[i], b = P[i + 1], o = new Array(40);
    for (var j = 0; j < 40; j++) o[j] = a[j] + (b[j] - a[j]) * w;
    return o;
  };

  /** A mannequin made of round-capped strokes. Points (see STICK in tools/fig/rl_env.py): 0 head 1 chest 2 waist 3 pelvis, right leg 4 hip 5 knee
   *  6 ankle 7 heel 8 toe, left leg 9..13, right arm 14 shoulder 15 elbow 16 hand, left arm 17..19.  The viewer stands front right, so the
   *  left limbs are the far ones (drawn first, darker).  opts: {ghost: true} draws a thin outline figure instead.
   *  Returns set(pts, ox, oy, pxPerMetre, tint) with (ox, oy) the screen position of the world origin on the floor; tint: 0..1 towards red. */
  K.stick = function (parent, opts) {
    opts = opts || {};
    var g = A.el('g', {}, parent);
    var FAR = '#5b6067', MID = '#7f858d', NEAR = '#aab0b8', RED = [255, 107, 94];
    var segs = [ // [i, j, width in metres, shade]
      [12, 13, 0.056, FAR], [10, 11, 0.098, FAR], [9, 10, 0.12, FAR], [17, 18, 0.08, FAR], [18, 19, 0.064, FAR],
      [3, 2, 0.2, MID], [2, 1, 0.21, MID],
      [7, 8, 0.056, NEAR], [5, 6, 0.098, NEAR], [4, 5, 0.12, NEAR], [14, 15, 0.08, NEAR], [15, 16, 0.064, NEAR]];
    var lines = segs.map(function (s) {
      return A.el('line', opts.ghost ? { stroke: '#6d7278', 'stroke-width': 2, 'stroke-linecap': 'round', 'stroke-dasharray': '2 5', fill: 'none' }
                                     : { stroke: s[3], 'stroke-linecap': 'round', fill: 'none' }, g);
    });
    var head = A.el('circle', opts.ghost ? { fill: 'none', stroke: '#6d7278', 'stroke-width': 2, 'stroke-dasharray': '2 5' } : { fill: NEAR }, g);
    var hands = opts.ghost ? [] : [A.el('circle', { fill: FAR }, g), A.el('circle', { fill: NEAR }, g)];
    if (!opts.ghost) { g.insertBefore(hands[0], lines[5]); }                    // the far hand goes behind the torso
    function mix(hex, t) {
      var r = parseInt(hex.substr(1, 2), 16), gg = parseInt(hex.substr(3, 2), 16), b = parseInt(hex.substr(5, 2), 16);
      return 'rgb(' + Math.round(r + (RED[0] - r) * t) + ',' + Math.round(gg + (RED[1] - gg) * t) + ',' + Math.round(b + (RED[2] - b) * t) + ')';
    }
    return function set(p, ox, oy, sc, tint) {
      var m = sc / 1000;
      for (var i = 0; i < segs.length; i++) {
        var s = segs[i], at = { x1: (ox + p[2 * s[0]] * m).toFixed(1), y1: (oy - p[2 * s[0] + 1] * m).toFixed(1), x2: (ox + p[2 * s[1]] * m).toFixed(1), y2: (oy - p[2 * s[1] + 1] * m).toFixed(1) };
        if (!opts.ghost) { at['stroke-width'] = (s[2] * sc).toFixed(1); at.stroke = tint ? mix(s[3], tint) : s[3]; }
        A.set(lines[i], at);
      }
      for (i = 0; i < hands.length; i++) {
        var hp = i ? 16 : 19;
        A.set(hands[i], { cx: (ox + p[2 * hp] * m).toFixed(1), cy: (oy - p[2 * hp + 1] * m).toFixed(1), r: (0.042 * sc).toFixed(1), fill: tint ? mix(i ? NEAR : FAR, tint) : (i ? NEAR : FAR) });
      }
      var hd = { cx: (ox + p[0] * m).toFixed(1), cy: (oy - p[1] * m).toFixed(1), r: (0.09 * sc).toFixed(1) };
      if (!opts.ghost) hd.fill = tint ? mix(NEAR, tint) : NEAR;
      A.set(head, hd);
    };
  };

  // ---- small text helpers for SVG
  var MI = 'font-family:' + A.MATH + ';font-style:italic;font-size:1.16em';
  /** a math symbol in the italic face KaTeX uses */
  K.mi = function (s) { return '<tspan style="' + MI + '">' + s + '</tspan>'; };
  /** symbol with a subscript (down = true) or superscript; `rest` is the text that follows, back on the baseline */
  K.ss = function (base, idx, down, rest) {
    var d = down ? 7 : -10;
    return '<tspan style="' + MI + '">' + base + '</tspan><tspan dy="' + d + '" style="' + MI + ';font-size:.82em">' + idx + '</tspan><tspan dy="' + (-d) + '">' + (rest || '​') + '</tspan>';
  };
  K.text = function (parent, x, y, html, size, fill, weight, anchor) {
    var n = A.el('text', { x: x, y: y, 'text-anchor': anchor || 'start', style: 'font:' + (weight || 700) + ' ' + size + 'px ' + A.FONT + ';fill:' + (fill || '#fff') + ';white-space:pre' }, parent);
    n.innerHTML = html;
    return n;
  };
  K.fix = function (v, d) { return v.toFixed(d).replace('-', '−'); };
})();
